import{_ as t,C as o,c as i,o as n,j as r,G as l,al as s,a as d}from"./chunks/framework.CT7RwC5a.js";const k=JSON.parse('{"title":"Автогиро Каркаси","description":"","frontmatter":{},"headers":[],"relativePath":"uk/frames_autogyro/index.md","filePath":"uk/frames_autogyro/index.md"}'),u={name:"uk/frames_autogyro/index.md"};function f(p,e,h,c,m,g){const a=o("LinkedBadge");return n(),i("div",null,[e[0]||(e[0]=r("h1",{id:"автогиро-каркаси",tabindex:"-1"},[d("Автогиро Каркаси "),r("a",{class:"header-anchor",href:"#автогиро-каркаси","aria-label":'Permalink to "Автогиро Каркаси"'},"​")],-1)),l(a,{type:"warning",text:"Experimental",url:"../airframes/#experimental-vehicles"}),e[1]||(e[1]=s('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Support for autogyro frames is <a href="./../airframes/#experimental-vehicles">experimental</a>. Maintainer volunteers, <a href="./../contribute/">contribution</a> of new features, new frame configurations, or other improvements would all be very welcome!</p></div><p>An <a href="https://en.wikipedia.org/wiki/Autogyro" target="_blank" rel="noreferrer">Autogyro</a> is a type of <a href="https://en.wikipedia.org/wiki/Rotorcraft" target="_blank" rel="noreferrer">rotary-wing</a>. Порівняно з іншими конструкціями він має наступні переваги:</p><ul><li>Можливість злітати та сідати, використовуючи лише дуже коротку злітну смугу (порівняно з фіксованим крилом).</li><li>Висока стійкість до погодних умов, особливо поривів вітру.</li><li>Володіння неприводним ротором, що дозволяє йому працювати в режимі авторотації (один із аварійних режимів гелікоптера). Отже, йому не потрібно активно змінювати режим польоту у разі відмови (йому не потрібен парашут або інші активно працюючі пристрої). Таким чином, політ за своєю суттю є стабільним у будь-який час.</li><li>Absence of a <a href="https://en.wikipedia.org/wiki/Downwash" target="_blank" rel="noreferrer">downwash</a> during take-off or landing creating an unwanted swirling of dust.</li><li><a href="https://en.wikipedia.org/wiki/Lift-to-drag_ratio" target="_blank" rel="noreferrer">Low lift-to-drag ratio</a> that can be adjusted by construction parameters. Ця здатність може бути корисною, оскільки безпілотний автогир не може летіти дуже далеко у разі відмови (як у випадку звичайного літака), проте польот все ще безпечний, і літак не падає (як у випадку багтороторного або гелікоптера).</li></ul><h2 id="підтримувані-конструкціі" tabindex="-1">Підтримувані конструкції <a class="header-anchor" href="#підтримувані-конструкціі" aria-label="Permalink to &quot;Підтримувані конструкції&quot;">​</a></h2><p>PX4 підтримує кілька автогирних конструкцій. The set of supported configurations can be seen in <a href="./../airframes/airframe_reference.html#autogyro">Airframes Reference &gt; Autogyro</a>.</p><h3 id="diy-конструкціі" tabindex="-1">DIY Конструкції <a class="header-anchor" href="#diy-конструкціі" aria-label="Permalink to &quot;DIY Конструкції&quot;">​</a></h3><p>У цьому розділі містяться журнали збірки/інструкції щодо складання та налаштування ряду Autogyro конструкцій.</p><ul><li><a href="./../frames_autogyro/thunderfly_auto_g2.html">ThunderFly Auto-G2 (Holybro pix32)</a> - Modified Autogyro RC model</li></ul><h3 id="повні-конструкціі-з-попередніми-налаштуваннями-px4" tabindex="-1">Повні конструкції з попередніми налаштуваннями PX4 <a class="header-anchor" href="#повні-конструкціі-з-попередніми-налаштуваннями-px4" aria-label="Permalink to &quot;Повні конструкції з попередніми налаштуваннями PX4&quot;">​</a></h3><p>У цьому розділі перелічені транспортні засоби, які продаються повністю зібраними та готові до польоту (RTF), з встановленим PX4.</p><ul><li><a href="https://docs.thunderfly.cz/instruments/TF-G2" target="_blank" rel="noreferrer">ThunderFly TF-G2</a> - Unmanned Autogyro Development Kit</li><li><a href="https://docs.thunderfly.cz/instruments/TF-G250" target="_blank" rel="noreferrer">ThunderFly TF-G250</a> - Atmospheric Sounding Aerological Autogyro</li></ul>',11))])}const y=t(u,[["render",f]]);export{k as __pageData,y as default};
